svg.script:
(function(){var s=document.documentElement;if(!s.classList)return;s.classList.add('js');
function set(n){if(n)s.setAttribute('data-focus',n);else s.removeAttribute('data-focus');}
var pinned=null,els=document.querySelectorAll('[data-fire]');
for(var i=0;i<els.length;i++){(function(el){var n=el.getAttribute('data-fire');
el.addEventListener('mouseenter',function(){set(n);});
el.addEventListener('mouseleave',function(){set(pinned);});
el.addEventListener('click',function(e){pinned=(pinned===n)?null:n;set(pinned);e.stopPropagation();});})(els[i]);}
s.addEventListener('click',function(){pinned=null;set(null);});})();
